-- Source: modules/domains/conversation/shiyu-conversation-implementation/src/main/resources/db/baseline/h2/schema/conversation/11_conversation.sql
-- Platform conversation source of truth. Messages are never duplicated into memory tables.
CREATE TABLE IF NOT EXISTS chat_conversation (
    id CHARACTER VARYING(64) NOT NULL,
    tenant_id BIGINT NOT NULL,
    owner_user_id BIGINT NOT NULL,
    scene_type CHARACTER VARYING(64) NOT NULL,
    title CHARACTER VARYING(255),
    status CHARACTER VARYING(16) NOT NULL,
    parent_conversation_id CHARACTER VARYING(64),
    branch_from_message_id CHARACTER VARYING(64),
    active_leaf_message_id CHARACTER VARYING(64),
    rolling_summary TEXT,
    platform CHARACTER VARYING(64),
    model CHARACTER VARYING(128),
    version BIGINT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL,
    updated_at TIMESTAMP NOT NULL,
    CONSTRAINT pk_chat_conversation PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_chat_conv_owner ON chat_conversation(tenant_id, owner_user_id, status);

CREATE TABLE IF NOT EXISTS chat_message (
    id CHARACTER VARYING(64) NOT NULL,
    tenant_id BIGINT NOT NULL,
    conversation_id CHARACTER VARYING(64) NOT NULL,
    parent_message_id CHARACTER VARYING(64),
    source_message_id CHARACTER VARYING(64),
    role CHARACTER VARYING(16) NOT NULL,
    content TEXT NOT NULL,
    content_parts TEXT,
    tool_call TEXT,
    status CHARACTER VARYING(16) NOT NULL,
    sequence INTEGER NOT NULL,
    generation_id CHARACTER VARYING(64),
    created_at TIMESTAMP NOT NULL,
    updated_at TIMESTAMP NOT NULL,
    CONSTRAINT pk_chat_message PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_chat_message_conv_seq ON chat_message(tenant_id, conversation_id, sequence);

CREATE TABLE IF NOT EXISTS chat_generation_run (
    id CHARACTER VARYING(64) NOT NULL,
    tenant_id BIGINT NOT NULL,
    conversation_id CHARACTER VARYING(64) NOT NULL,
    input_message_id CHARACTER VARYING(64),
    assistant_message_id CHARACTER VARYING(64),
    runtime_run_id CHARACTER VARYING(64),
    speaker_id CHARACTER VARYING(128),
    platform CHARACTER VARYING(64),
    model CHARACTER VARYING(128),
    status CHARACTER VARYING(24) NOT NULL,
    prompt_tokens BIGINT DEFAULT 0,
    completion_tokens BIGINT DEFAULT 0,
    latency_ms BIGINT DEFAULT 0,
    error_code CHARACTER VARYING(128),
    last_event_sequence INTEGER DEFAULT -1,
    cancel_requested BOOLEAN NOT NULL DEFAULT FALSE,
    version BIGINT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL,
    updated_at TIMESTAMP NOT NULL,
    CONSTRAINT pk_chat_generation_run PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_chat_generation_run_conv ON chat_generation_run(tenant_id, conversation_id, created_at);

-- Database-level admission reservation.  It closes the check-then-insert
-- race for retries on the same active user message; the row is released when
-- the GenerationRun reaches any terminal state.
CREATE TABLE IF NOT EXISTS chat_generation_active (
    tenant_id BIGINT NOT NULL,
    conversation_id CHARACTER VARYING(64) NOT NULL,
    input_message_id CHARACTER VARYING(64) NOT NULL,
    generation_id CHARACTER VARYING(64) NOT NULL,
    created_at TIMESTAMP NOT NULL,
    CONSTRAINT pk_chat_generation_active PRIMARY KEY (tenant_id, conversation_id, input_message_id),
    CONSTRAINT uk_chat_generation_active_run UNIQUE (generation_id)
);

-- Generation events are a typed projection of AI_RUN_EVENT. Do not create a
-- second physical stream.

CREATE TABLE IF NOT EXISTS chat_idempotency_key (
    tenant_id BIGINT NOT NULL,
    owner_user_id BIGINT NOT NULL,
    key_value CHARACTER VARYING(128) NOT NULL,
    operation CHARACTER VARYING(64) NOT NULL,
    resource_id CHARACTER VARYING(64) NOT NULL,
    created_at TIMESTAMP NOT NULL,
    CONSTRAINT pk_chat_idempotency_key PRIMARY KEY (tenant_id, owner_user_id, key_value, operation)
);

CREATE INDEX IF NOT EXISTS idx_chat_generation_active_tenant ON chat_generation_active(tenant_id);
CREATE INDEX IF NOT EXISTS idx_chat_idempotency_key_tenant ON chat_idempotency_key(tenant_id);

